import * as T from 'three';
import {OrbitControls} from './orbit.js';
const $=s=>document.querySelector(s);
const bodySystems=[['skeletal','Skeleton','#d9cfaf','Bones support the body, protect internal organs, and provide attachment points for muscles.'],['muscular','Muscles','#ae6458','Skeletal muscles produce movement, stabilize joints, and maintain posture.'],['cardiac','Heart','#b45e58','The heart pumps blood through the lungs and the rest of the body.'],['arterial','Arteries','#c65b4b','Arteries carry blood away from the heart.'],['venous','Veins','#5d87a9','Veins carry blood toward the heart.'],['nervous','Nervous system','#d6b564','The brain, spinal cord, and peripheral nerves process and transmit signals.'],['respiratory','Respiratory','#c3929b','The airways and lungs support breathing and gas exchange.'],['digestive','Digestive','#bb936e','The digestive system processes food, absorbs nutrients, and eliminates waste.'],['urinary','Urinary','#ac785e','The urinary system filters blood, regulates fluid balance, and removes waste in urine.'],['lymphatic','Lymphatic','#8caa7e','Lymphatic structures return tissue fluid to the circulation and support immune function.'],['endocrine','Endocrine','#bc9f9f','Endocrine structures release hormones that regulate body functions.'],['sensory','Sensory organs','#a4c4c9','Specialized sensory structures support sight, hearing, and balance.'],['reproductive','Reproductive','#b99b90','This reference includes male reproductive anatomy.'],['connective','Connective tissue','#aec5b5','Connective tissues support and connect structures throughout the body.'],['integumentary','Body surface','#bda68c','The outer body surface provides an anatomical reference.']];
const heartSystems=[['walls','Heart walls','#ad5556','The heart wall surrounds the chambers. Hide this layer to inspect internal structures.'],['chambers','Chamber cavities','#db8790','These solid volumes represent the spaces inside the four chambers, not their muscular walls.'],['valves','Valve leaflets','#e5c6a3','Valve cusps and leaflets help maintain forward blood flow.'],['coronary','Coronary vessels','#c55256','Coronary arteries supply the heart muscle; cardiac veins return blood from it.'],['vessels','Great vessels','#bb657a','Selected great vessels: ascending aorta, aortic arch and pulmonary trunk.']];
let systems=bodySystems,categories=[],heartGroups={},category='body',allowed=null,categorySize=1.8,indicator=null;
const visible=new Set(bodySystems.map(s=>s[0]).filter(s=>s!=='integumentary'&&s!=='connective'));
const group=m=>category==='heart'?(heartGroups[m.userData.id]||m.userData.system):m.userData.system;
const included=m=>!allowed||allowed.has(m.userData.id);
const meshes=[],byId=new Map();let categoryCenter=new T.Vector3(0,.85,0);let atlas,selected=null,isolated=false,explosion=0,controls,camera,renderer,scene,dirty=true;
function buttons(){ $('#systems').innerHTML='';systems.forEach(([id,name,color])=>{const b=document.createElement('button');b.className='system'+(visible.has(id)?' active':'');b.setAttribute('aria-pressed',visible.has(id));b.innerHTML=`<span class="dot" style="background:${color}"></span><span>${name}</span><span class="eye">${visible.has(id)?'◉':'○'}</span>`;b.onclick=()=>{visible.has(id)?visible.delete(id):visible.add(id);isolated=false;update();buttons()};$('#systems').append(b)});$('#toggleAll').textContent=visible.size?'Hide all':'Show all'}
function update(){for(const m of meshes){const p=m.userData; m.visible=included(m)&&(isolated?m===selected:visible.has(group(m))||m===selected);const i=systems.findIndex(s=>s[0]===group(m)),angle=i/systems.length*Math.PI*2;m.position.set(Math.sin(angle)*explosion*categorySize*.38,(p.center.y-(categoryCenter?.y??.85))*explosion*.7,Math.cos(angle)*explosion*categorySize*.38);m.material.emissive.set(m===selected?'#0d727a':'#000000');m.material.emissiveIntensity=m===selected?.55:0}$('#isolate').textContent=isolated?'Show surrounding anatomy':'Isolate structure ↗';dirty=true}
function frame(view='front',focus=false){if(!camera)return;const box=new T.Box3();const items=focus&&selected?[selected]:meshes.filter(m=>m.visible);items.forEach(m=>box.expandByObject(m));const target=box.isEmpty()?categoryCenter.clone():box.getCenter(new T.Vector3());const size=box.isEmpty()?new T.Vector3(.7,1.8,.4):box.getSize(new T.Vector3());const distance=Math.max(.06,Math.max(size.x/Math.min(camera.aspect,1),size.y,size.z)/(2*Math.tan(T.MathUtils.degToRad(camera.fov/2)))*1.3);const dir=view==='back'?new T.Vector3(0,0,-1):view==='side'?new T.Vector3(1,0,0):new T.Vector3(.12,.015,1).normalize();controls.target.copy(target);camera.position.copy(target).addScaledVector(dir,distance);controls.update();dirty=true;}
function select(m){if(!m)return;selected=m;const s=systems.find(s=>s[0]===group(m));$('#detailSystem').textContent=s[1];$('#detailName').textContent=m.userData.name;$('#detailCopy').textContent=s[3];$('#detailId').textContent=m.userData.id;$('#detail').hidden=false;update();if(isolated)frame('front',true)}
function clear(){selected=null;isolated=false;$('#detail').hidden=true;update();frame()}
buttons();$('#toggleAll').onclick=()=>{if(visible.size)visible.clear();else systems.forEach(s=>{if(s[0]!=='integumentary')visible.add(s[0])});isolated=false;buttons();update()};$('#about').onclick=()=>$('#aboutDialog').showModal();$('#closeAbout').onclick=()=>$('#aboutDialog').close();$('#aboutDialog').onclick=e=>{if(e.target===$('#aboutDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};$('#clear').onclick=clear;$('#closeDetail').onclick=clear;$('#isolate').onclick=()=>{isolated=!isolated;update();frame('front',isolated)};
$('#search').addEventListener('input',()=>{const query=$('#search').value.trim().toLowerCase();const r=$('#results');r.replaceChildren();r.hidden=!query;if(!query)return;const found=(atlas?.parts||[]).filter(p=>!allowed||allowed.has(p.id)).filter(p=>p.name.toLowerCase().includes(query)||p.id.toLowerCase().includes(query)).slice(0,35);if(!found.length){const p=document.createElement('p');p.textContent=atlas?'No structures found. Try “heart” or “femur”.':'The anatomy catalogue is loading…';r.append(p)}for(const p of found){const b=document.createElement('button');b.textContent=p.name;b.onclick=()=>{const m=byId.get(p.id);if(!m){b.textContent='This structure is still loading…';return}isolated=true;select(m);r.hidden=true;$('#search').value=''};r.append(b)}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&e.target.tagName!=='INPUT'){e.preventDefault();$('#search').focus()}if(e.key==='Escape'){ $('#results').hidden=true;if(selected)clear()}});
addEventListener('resize',()=>{if(!indicator)return;const host=$('#categories');const active=host.querySelector('.category.active');if(active){indicator.style.left=active.offsetLeft+'px';indicator.style.width=active.offsetWidth+'px';}});
try{
 renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setClearColor('#101820');renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;$('#scene').append(renderer.domElement);renderer.domElement.setAttribute('aria-label','3D human anatomy. Drag to rotate, scroll to zoom, or click to select a structure.');scene=new T.Scene();camera=new T.PerspectiveCamera(35,1,.005,100);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=false;controls.minDistance=.05;controls.maxDistance=12;controls.addEventListener('change',()=>dirty=true);scene.add(new T.HemisphereLight(0xffffff,0x879589,2.1));for(const [x,y,z,intensity] of [[-3,4,5,2.7],[3,2,-3,1.7]]){const light=new T.DirectionalLight(0xffffff,intensity);light.position.set(x,y,z);scene.add(light)}const floor=new T.Mesh(new T.CircleGeometry(.5,96),new T.MeshBasicMaterial({color:0xe3e8e2,side:T.DoubleSide}));floor.rotation.x=-Math.PI/2;floor.position.y=-.015;floor.visible=false;scene.add(floor);const ring=new T.Mesh(new T.RingGeometry(.53,.532,96),new T.MeshBasicMaterial({color:0xc7d3c9,side:T.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.y=-.014;ring.visible=false;scene.add(ring);
 new ResizeObserver(()=>{const w=$('#scene').clientWidth,h=$('#scene').clientHeight;camera.aspect=w/h;camera.updateProjectionMatrix();renderer.setSize(w,h);frame('front',isolated)}).observe($('#scene'));
 function animate(){requestAnimationFrame(animate);if(dirty){renderer.render(scene,camera);dirty=false}}animate();
 for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));$('#viewLabel').textContent=({front:'Anterior perspective',back:'Posterior perspective',side:'Lateral perspective'})[b.dataset.view];frame(b.dataset.view,isolated)};
 $('#reset').onclick=()=>{explosion=0;$('#explode').value=0;clear()};$('#zoomIn').onclick=()=>{camera.position.sub(controls.target).multiplyScalar(.8).add(controls.target);controls.update();dirty=true};$('#zoomOut').onclick=()=>{camera.position.sub(controls.target).multiplyScalar(1.25).add(controls.target);controls.update();dirty=true};$('#explode').oninput=e=>{explosion=Number(e.target.value)/100;isolated=false;update();frame()};
 const ray=new T.Raycaster(),point=new T.Vector2();let down;renderer.domElement.addEventListener('pointerdown',e=>down=[e.clientX,e.clientY]);renderer.domElement.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>5)return;const r=renderer.domElement.getBoundingClientRect();point.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(point,camera);const hits=ray.intersectObjects(meshes.filter(m=>m.visible&&m.userData.system!=='integumentary'),false);if(hits.length)select(hits[0].object)});
 const response=await fetch('./models/atlas.json');if(!response.ok)throw Error('The anatomy catalogue could not be loaded.');atlas=await response.json();const catalogResponse=await fetch('./categories.json');if(!catalogResponse.ok)throw Error('Categories could not be loaded.');const catalog=await catalogResponse.json();categories=catalog.categories;heartGroups=catalog.heartGroups;const brainSet=new Set(categories.find(c=>c.id==='brain').parts);atlas.parts.forEach(p=>{if(p.system==='cardiac'&&brainSet.has(p.id))p.system='nervous'});renderCategories();$('#partCount').textContent=atlas.parts.length.toLocaleString()+' structures';let completed=0,index=0;
 async function chunk(i){const c=atlas.chunks[i],res=await fetch('.'+c.gzip);if(!res.ok)throw Error('An anatomy file could not be loaded.');let buffer=await res.arrayBuffer();const magic=new Uint8Array(buffer,0,2);if(magic[0]===31&&magic[1]===139)buffer=await new Response(new Blob([buffer]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();if(buffer.byteLength!==c.bytes)throw Error('An anatomy file is incomplete.');for(const p of atlas.parts.filter(p=>p.chunk===i)){const geo=new T.BufferGeometry();geo.setAttribute('position',new T.BufferAttribute(new Float32Array(buffer,p.positions,p.vertexCount*3),3));geo.setAttribute('normal',new T.BufferAttribute(new Int16Array(buffer,p.normals,p.vertexCount*3),3,true));geo.setIndex(new T.BufferAttribute(new Uint32Array(buffer,p.indices,p.indexCount),1));const sys=bodySystems.find(s=>s[0]===p.system);const material=new T.MeshStandardMaterial({color:sys?.[2]||'#b8bdaf',roughness:.58,metalness:.03,side:T.DoubleSide,transparent:p.system==='integumentary',opacity:p.system==='integumentary'?.12:1,depthWrite:p.system!=='integumentary'});const m=new T.Mesh(geo,material);m.userData={...p,center:new T.Vector3().fromArray(p.bounds[0]).add(new T.Vector3().fromArray(p.bounds[1])).multiplyScalar(.5)};meshes.push(m);byId.set(p.id,m);scene.add(m)}completed++;$('#progress').textContent=`${Math.round(completed/atlas.chunks.length*100)}% · Loading anatomical structures`;update()}
 await Promise.all(Array.from({length:3},async()=>{while(index<atlas.chunks.length)await chunk(index++)}));$('#loading').hidden=true;setCategory(category);
}catch(error){$('#loading').hidden=false;$('#loading').innerHTML='<strong>Unable to load the 3D atlas</strong><span></span><button style="pointer-events:auto;text-decoration:underline" onclick="location.reload()">Try again</button>';$('#loading span').textContent=error.message||'Try a browser with WebGL enabled.';console.error(error)}

function renderCategories(){const host=$('#categories');host.replaceChildren();for(const c of categories){const b=document.createElement('button');b.className='category'+(c.id===category?' active':'');b.setAttribute('aria-pressed',c.id===category);b.innerHTML=`<span class="category-index">${String(categories.indexOf(c)+1).padStart(2,'0')}</span><span>${c.name}</span><small>${c.id==='body'?'ALL':c.parts.length}</small>`;b.onclick=()=>setCategory(c.id);host.append(b);}
 if(!indicator){indicator=document.createElement('div');indicator.className='category-indicator';indicator.setAttribute('aria-hidden','true');}
 host.append(indicator);
 requestAnimationFrame(()=>{const active=host.querySelector('.category.active');if(active){indicator.style.left=active.offsetLeft+'px';indicator.style.width=active.offsetWidth+'px';}});}
function setCategory(id){category=id;const c=categories.find(x=>x.id===id);allowed=id==='body'?null:new Set(c.parts);selected=null;isolated=false;explosion=0;$('#explode').value=0;$('#search').value='';$('#results').hidden=true;$('#detail').hidden=true;
 systems=id==='heart'?heartSystems:bodySystems.filter(s=>id==='body'||atlas.parts.some(p=>allowed.has(p.id)&&p.system===s[0]));visible.clear();systems.forEach(s=>{if(id!=='body'||(s[0]!=='integumentary'&&s[0]!=='connective'))visible.add(s[0]);});
 const box=new T.Box3();meshes.filter(included).forEach(m=>{m.position.set(0,0,0);box.expandByObject(m)});if(!box.isEmpty()){box.getCenter(categoryCenter);categorySize=box.getSize(new T.Vector3()).length();}
 for(const m of meshes){const s=systems.find(s=>s[0]===group(m))||bodySystems.find(s=>s[0]===m.userData.system);let color=s?.[2]||'#b8bdaf';if(id==='heart'&&group(m)==='coronary'&&/vein|sinus/i.test(m.userData.name))color='#617dae';if(id==='heart'&&group(m)==='chambers'&&/right/i.test(m.userData.name))color='#758bb8';m.material.color.set(color);}
 $('#categoryName').textContent=c.name;$('#categoryNote').textContent=c.note;$('#referenceName').textContent=id==='body'?'Adult male anatomy':c.name+' anatomy';$('#partCount').textContent=(id==='body'?atlas.parts.length:c.parts.length).toLocaleString()+' structures';$('#layerCount').textContent=systems.length+' layers';$('#layerTitle').textContent=id==='body'?'Body systems':'Anatomical layers';$('#internalView').hidden=id!=='heart';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='front'));$('#viewLabel').textContent='Anterior perspective';renderCategories();buttons();update();frame();}
$('#internalView').onclick=()=>{visible.delete('walls');isolated=false;buttons();update();frame();};
